class Solution:
    def removeAlmostEqualCharacters(self, word: str) -> int:
        n = len(word)
        dp = [[float('inf')] * 26 for _ in range(n)]

        # Base case for the first character
        for i in range(26):
            dp[0][i] = 1 if ord(word[0]) - ord('a') != i else 0

        for i in range(1, n):
            for j in range(26):  # current char is j
                cost = 1 if ord(word[i]) - ord('a') != j else 0

                min_prev_cost = float('inf')
                for k in range(26): # previous char was k
                    if not (abs(j - k) <= 1):
                        min_prev_cost = min(min_prev_cost, dp[i-1][k])

                dp[i][j] = cost + min_prev_cost

        return min(dp[n-1])
